.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 19px;
  border: 1px solid color-mix(in oklch, var(--foreground) 12%, transparent);
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  transition:
    background-color 160ms,
    transform 140ms;
}.ds-primary {
  background: var(--primary);
  color: var(--primary-foreground);
  border-color: transparent;
}.ds-primary:hover {
  background: var(--primary-strong);
}.ds-button:active {
  transform: scale(0.97);
}.ds-button:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

.ds-button {
  display: inline-flex;
