}.ds-button:hover {
  background: var(--v11-track);
}.ds-button:active {
  transform: scale(0.97);
}.ds-button:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

.ds-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border-radius: 24px;
  border: 1px solid var(--v11-line);
  background:
    radial-gradient(
      130% 110% at 100% 0%,
      color-mix(in oklch, var(--primary) 8%, transparent),
      transparent 62%
    ),
    color-mix(in oklch, var(--card) 58%, transparent);
  backdrop-filter: blur(26px) saturate(150%);
  box-shadow: var(--v11-shadow);
  transition:
    transform 260ms var(--pc-spring),
    border-color 260ms,
    box-shadow 300ms;
}.ds-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  padding: 1.6px;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.5;
  background: conic-gradient(
    from 0deg,
    transparent 0deg,
    color-mix(in oklch, var(--foreground) 60%, transparent) 8deg,
    white 26deg,
    white 44deg,
    color-mix(in oklch, var(--foreground) 60%, transparent) 62deg,
    transparent 74deg,
    transparent 180deg,
    color-mix(in oklch, var(--foreground) 60%, transparent) 188deg,
    white 206deg,
    white 224deg,
    color-mix(in oklch, var(--foreground) 60%, transparent) 242deg,
    transparent 254deg
  );
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
}.ds-card {padding:22px;color:var(--foreground);font-family:var(--font-app)} .ds-card h3 {font-size:15px;font-weight:600} @media(hover:hover){.ds-card:hover {
    transform: translateY(-3px);
    border-color: color-mix(in oklch, var(--foreground) 17%, transparent);
    box-shadow:
      inset 0 1px 0 rgb(255 255 255 / 10%),
      0 34px 72px -34px rgb(0 0 0 / 72%);
  }
}} @media(prefers-reduced-motion:reduce){.ds-card {transition:none}.ds-card:hover {transform:none}}

.ds-composer {
  position: relative;
  width: 100%;
  border-radius: 26px;
  padding: 14px 16px;
  border: 1px solid var(--v11-line);
  background: color-mix(in oklab, var(--sidebar) 94%, black);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 6%),
    0 20px 44px -28px rgb(0 0 0 / 60%);
}.ds-composer:focus-within {
  border-color: color-mix(in oklab, var(--primary) 50%, transparent);
}.ds-composer textarea {width:100%;min-height:40px;background:transparent;color:var(--foreground);border:0;padding:10px 6px;font:16px/1.4 var(--font-app)} .ds-composer textarea:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }

.ds-period {
  display: flex;
  gap: 3px;
  padding: 3px;
  background: var(--v11-track);
  border-radius: 999px;
}.ds-period a {
  display: flex;
  align-items: center;
  min-height: 30px;
  padding: 0 12px;
  font-size: 11px;
  color: var(--muted-foreground);
  border-radius: 999px;
}.ds-period a[aria-current="page"] {
  background: var(--primary);
  color: var(--primary-foreground);
}.ds-period a:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
